--region handler
---关闭按钮点击回调
function CardProgressionEquipmentGradeLevelUpDialog:BtnCloseOnClickHandler()
    Events.Broadcast(Constants.EventNames.CardProgressEquipSelectClear)
    self:CloseDialog()
end

---升级按钮点击回调
function CardProgressionEquipmentGradeLevelUpDialog:BtnUpgradeOnClickHandler()
    local equipDojo = self:GetEquipDojo()
    local cost = self:GetUpgradeCost()
    if not GoodsUtils.CheckConsumeDataCondition(cost, 10) then
        return
    end
    for i, v in ipairs(cost) do
        local num = GoodsUtils.GetThingNo(v.goodsId)
        if num < checkInt(v.goodsNum) then
            GameUtils.Toast(localize("道具不足"))
            return
        end
        v.num = -(v.goodsNum)
    end

    self._befEquipDojo = clone(equipDojo)
    CardProgressionMgr:RequestOverseaEquipmentLevelUp({playerEquipmentId = equipDojo.id}, cost)
end

---快速升级按钮点击回调
function CardProgressionEquipmentGradeLevelUpDialog:BtnQuickUpgradeOnClickHandler()
    local equipDojo = self:GetEquipDojo()
    local canUpgrade, consume, star, level = EquipUtils.CalculateQuickUpgradeConsume(equipDojo)
    if not canUpgrade then
        -- GameUtils.Toast(localize("道具不足"))
        local cost = self:GetUpgradeCost()
        if not GoodsUtils.CheckConsumeDataCondition(cost, 10) then
            return
        end
        return
    end
    local tips = nil
    if level == 0 then
        tips = localize("快速升级将消耗以下材料，将装备提升至<color=#e71f55>_num1_星</color>，是否确认？", {_num1_ = star})
    else
        tips = localize("快速升级将消耗以下材料，将装备提升至<color=#e71f55>_num1_星+_num2_</color>，是否确认？", {_num1_ = star, _num2_ = level})
    end
    for _, v in ipairs(consume) do
        v.forceText = v.goodsNum
        v.num = -v.goodsNum
    end
    GameUtils.SecondConfirm(tips, function()
        CardProgressionMgr:RequestOverseaEquipmentQuickUpgrade({playerEquipmentId = equipDojo.id, targetLevel = level, targetStar = star}, consume)
        if checkInt(equipDojo.star) ~= star then
            self:CloseDialog()
        end
    end, nil, nil, 4, consume, true) 
end

---跳转事件处理
function CardProgressionEquipmentGradeLevelUpDialog:ExecuteJumpEventHandler()
    self:CloseDialog()
end

---升级结束事件处理
function CardProgressionEquipmentGradeLevelUpDialog:LevelUpFinishEventHandler(equipDojo)
    self._aniCo = cs_coroutine.start(function()
        self:ShowPointChange(equipDojo)
        
        if checkInt(equipDojo.level) == CardProgressionConstants.EquipmentLevelUpperLimit then
            if checkInt(equipDojo.star) == EquipUtils.GetEquipmentStarMaxByDojo(equipDojo) then
                Events.Broadcast(Constants.EventNames.CardProgressEquipSelectClear)
                Events.Broadcast(Constants.EventNames.CardProgressEquipStarUpFinish, equipDojo)
            else
                EquipUtils.EnterCultivateEquipDialog(equipDojo)
            end
            self:CloseDialog()
        else
            self._equipDojo = checkTable(equipDojo)
            self:RefreshView()
            CfUtils.StartCoroutineWithBlocker(function()
                xTry(function()
                    CfUtils.PlayAnimation(self.AnmRoot, "CultivateOverseaEquipmentUpgradeDialog_LevelUp")
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
                end)
            end)
        end
    end)
end
--endregion handler

