---刷新界面
function CardProgressionEquipmentGradeLevelUpDialog:RefreshView()
    self:RefreshCurrencyBar()
    self:RefreshEquipmentGoods()
    self:RefreshAttr()
    self:RefreshBtn()
    self:RefreshUpgradeCost()
end

---刷新货币栏
function CardProgressionEquipmentGradeLevelUpDialog:RefreshCurrencyBar()
    local goodsList = {Constants.Currency.GoldId}
    CfUtils.RefreshTopGoods(goodsList)
end

---刷新装备道具
function CardProgressionEquipmentGradeLevelUpDialog:RefreshEquipmentGoods()
    local equipDojo = clone(self:GetEquipDojo())
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)

    CfUtils.FillText(self.TxtEquipName, goodsVo.name)
    
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.CurGoodsNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end

    equipDojo.level = checkInt(equipDojo.level) + 1
    ---@type GoodNodeMB
    local mbEnv2 = CfUtils.GetLuaScr(self.AfterGoodsNode.gameObject, GoodNodePrefabPath)
    if mbEnv2 then
        mbEnv2:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end
end

---刷新属性
function CardProgressionEquipmentGradeLevelUpDialog:RefreshAttr()
    local equipDojo = self:GetEquipDojo()
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = cardConfMgr:GetBasicAttr(attrAddVo.attrId)
    local attrName = cardConfMgr:GetBasicAttrNameByType(attrAddVo.attrId)

    CfUtils.FillImage(self.ImgAttributeIcon, attrVo.icon)
    CfUtils.FillText(self.TxtAttrNameBefore, attrName)
    CfUtils.FillText(self.TxtNumBefore, EquipUtils.CalculateEquipmentMainAttr(equipDojo, true))
    local afterDojo = clone(equipDojo)
    afterDojo.level = checkInt(afterDojo.level) + 1
    CfUtils.FillText(self.TxtNumAfter, EquipUtils.CalculateEquipmentMainAttr(afterDojo, true))
end

---刷新按钮
function CardProgressionEquipmentGradeLevelUpDialog:RefreshBtn()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local equipLevelUpTimes = checkInt(playerDojo.equipLevelUpTimes)
    local limit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentQuickUpgradeLimit))
    if equipLevelUpTimes >= limit then
        CfUtils.SetActive(self.Quick, true)
        CfUtils.SetActive(self.QuickCommonBtnConsumePop, false)
    else
        CfUtils.SetActive(self.Quick, false)
    end
end

---刷新升级消耗
function CardProgressionEquipmentGradeLevelUpDialog:RefreshUpgradeCost()
    local cost = self:GetUpgradeCost()

    -- 处理金币消耗
    local goldNum = nil
    for i, v in ipairs(cost) do
        if checkInt(v.goodsId) == Constants.Currency.GoldId then
            goldNum = v.goodsNum
            table.remove(cost, i)
            break
        end
    end
    if goldNum then
        CfUtils.SetActive(self.CommonBtnConsumePop, true)
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, Constants.Currency.GoldId, goldNum, false, false)
    else
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
    end
    
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsList, cost, false, false, true, true, true)
end

---关闭界面
function CardProgressionEquipmentGradeLevelUpDialog:CloseDialog()
    UIModule.CloseDialog(self.controller)
end

---获取EquipDojo
function CardProgressionEquipmentGradeLevelUpDialog:GetEquipDojo()
    return self._equipDojo
end

---获取升级前的装备Dojo
function CardProgressionEquipmentGradeLevelUpDialog:GetBefEquipDojo()
    return self._befEquipDojo or {}
end

---获取升级消耗
function CardProgressionEquipmentGradeLevelUpDialog:GetUpgradeCost()
    local equipDojo = self:GetEquipDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
    local params = {
        quality = goodsVo.quality,
        star    = equipDojo.star,
        level   = checkInt(equipDojo.level) + 1
    }
    local equipmentCNRVo = EquipUtils.GetEquipmentCNRVo(params)
    return parse_rewards(equipmentCNRVo.upgradeItem, equipmentCNRVo.upgradeNum)
end

---显示战力变化
function CardProgressionEquipmentGradeLevelUpDialog:ShowPointChange(equipDojo)
    local befDojo = self:GetBefEquipDojo()
    if checkInt(befDojo.playerCardId) == 0 then return end

    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(befDojo.playerCardId)
    local entity = CardProgressionUtils.GenerateEntityByCardDojo(cardDojo)
    local curPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    for k, v in pairs(entity.equipPart2Dojo) do
        if checkInt(v.id) == checkInt(befDojo.id) then
            entity.equipPart2Dojo[k] = befDojo
            break
        end
    end
    local befPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    CardProgressionUtils.ChangePointToast(curPoint - befPoint)
end
